// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/countries", wrapper.ListCountries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/countries/{iso}", wrapper.GetCountry)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/countries/{iso}", wrapper.SaveCountry)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/flights", wrapper.ListFlights)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/flights", wrapper.CreateFlight)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/flights/{id}", wrapper.DeleteFlight)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/flights/{id}", wrapper.UpdateFlight)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/register", wrapper.Register)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/users/{username}", wrapper.CheckUsername)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/oidc/config", wrapper.OidcConfig)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/user", wrapper.DeleteAccount)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/user", wrapper.GetAccount)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/user/profile", wrapper.UpdateProfile)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/user/settings", wrapper.SaveSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/user/password", wrapper.ChangePassword)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/public/{username}", wrapper.GetPublicTravel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/users", wrapper.ListUsers)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/admin/users/{id}", wrapper.DeleteUser)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/admin/users/{id}", wrapper.UpdateUser)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/admin/users/{id}/password", wrapper.ResetUserPassword)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/settings", wrapper.GetAdminSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/admin/settings", wrapper.SaveAdminSettings)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/admin/oidc", wrapper.DeleteOidcAdminConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/oidc", wrapper.GetOidcAdminConfig)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/admin/oidc", wrapper.SaveOidcAdminConfig)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/oidc/test", wrapper.TestOidcAdminConfig)

	return m
}

