// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// DeleteOidcAdminConfig Remove the saved configuration and turn OpenID Connect off
	// (DELETE /admin/oidc)
	DeleteOidcAdminConfig(ctx context.Context, request DeleteOidcAdminConfigRequestObject) (DeleteOidcAdminConfigResponseObject, error)
	// GetOidcAdminConfig OpenID Connect configuration of the installation
	// (GET /admin/oidc)
	GetOidcAdminConfig(ctx context.Context, request GetOidcAdminConfigRequestObject) (GetOidcAdminConfigResponseObject, error)
	// SaveOidcAdminConfig Save the OpenID Connect configuration and apply it without restart
	// (PUT /admin/oidc)
	SaveOidcAdminConfig(ctx context.Context, request SaveOidcAdminConfigRequestObject) (SaveOidcAdminConfigResponseObject, error)
	// TestOidcAdminConfig Check that the provider can be reached with this configuration
	// (POST /admin/oidc/test)
	TestOidcAdminConfig(ctx context.Context, request TestOidcAdminConfigRequestObject) (TestOidcAdminConfigResponseObject, error)
	// GetAdminSettings Settings of the whole installation
	// (GET /admin/settings)
	GetAdminSettings(ctx context.Context, request GetAdminSettingsRequestObject) (GetAdminSettingsResponseObject, error)
	// SaveAdminSettings Change the settings of the whole installation
	// (PUT /admin/settings)
	SaveAdminSettings(ctx context.Context, request SaveAdminSettingsRequestObject) (SaveAdminSettingsResponseObject, error)
	// ListUsers All accounts
	// (GET /admin/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// DeleteUser Delete another account with all its data and photos
	// (DELETE /admin/users/{id})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)
	// UpdateUser Change the role of an account
	// (PATCH /admin/users/{id})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
	// ResetUserPassword Set a new password for another account
	// (PUT /admin/users/{id}/password)
	ResetUserPassword(ctx context.Context, request ResetUserPasswordRequestObject) (ResetUserPasswordResponseObject, error)
	// Login Log in with username and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// OidcConfig Whether login with an OpenID Connect provider is available
	// (GET /auth/oidc/config)
	OidcConfig(ctx context.Context, request OidcConfigRequestObject) (OidcConfigResponseObject, error)
	// Register Create an account and log in
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// CheckUsername Whether a username is taken
	// (GET /auth/users/{username})
	CheckUsername(ctx context.Context, request CheckUsernameRequestObject) (CheckUsernameResponseObject, error)
	// ListCountries The user's countries without their long texts
	// (GET /countries)
	ListCountries(ctx context.Context, request ListCountriesRequestObject) (ListCountriesResponseObject, error)
	// GetCountry The full entry of a country, including its texts
	// (GET /countries/{iso})
	GetCountry(ctx context.Context, request GetCountryRequestObject) (GetCountryResponseObject, error)
	// SaveCountry Set status, visibility and details of a country
	// (PUT /countries/{iso})
	SaveCountry(ctx context.Context, request SaveCountryRequestObject) (SaveCountryResponseObject, error)
	// ListFlights The user's flights
	// (GET /flights)
	ListFlights(ctx context.Context, request ListFlightsRequestObject) (ListFlightsResponseObject, error)
	// CreateFlight Add a flight
	// (POST /flights)
	CreateFlight(ctx context.Context, request CreateFlightRequestObject) (CreateFlightResponseObject, error)
	// DeleteFlight Remove a flight
	// (DELETE /flights/{id})
	DeleteFlight(ctx context.Context, request DeleteFlightRequestObject) (DeleteFlightResponseObject, error)
	// UpdateFlight Change the visibility of a flight
	// (PATCH /flights/{id})
	UpdateFlight(ctx context.Context, request UpdateFlightRequestObject) (UpdateFlightResponseObject, error)
	// GetPublicTravel Public profile and public data of a user
	// (GET /public/{username})
	GetPublicTravel(ctx context.Context, request GetPublicTravelRequestObject) (GetPublicTravelResponseObject, error)
	// DeleteAccount Delete the account with all data and photos
	// (DELETE /user)
	DeleteAccount(ctx context.Context, request DeleteAccountRequestObject) (DeleteAccountResponseObject, error)
	// GetAccount Profile, settings and role of the user
	// (GET /user)
	GetAccount(ctx context.Context, request GetAccountRequestObject) (GetAccountResponseObject, error)
	// ChangePassword Change the password
	// (PUT /user/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// UpdateProfile Change profile fields
	// (PATCH /user/profile)
	UpdateProfile(ctx context.Context, request UpdateProfileRequestObject) (UpdateProfileResponseObject, error)
	// SaveSettings Replace the settings
	// (PUT /user/settings)
	SaveSettings(ctx context.Context, request SaveSettingsRequestObject) (SaveSettingsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

